/* Inventory discovery, NOT workflow certification. Each activated tab retains its action list. */
const {chromium}=require('playwright');const fs=require('node:fs');const path=require('node:path');
const routes=['dashboard','pos','counter','sales','purchases','purchases/new','vendors','parties?id=c1&role=Customer','finance','reconciliation','daybook','audit-ledger','accounts','products','expenses','reports','quotations','online-sales','warranty','notifications','settings/business','settings/sales','settings/products','settings/purchases','settings/money','settings/invoices','settings/team','settings/notifications','settings/personal','settings/data','subscription','support'];
const sizes=[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]];
const output=process.env.DEEP_INVENTORY_OUTPUT||'.superpowers/deep-audit/inventory';
async function main(){const {createServer}=await import('vite');const server=await createServer({server:{host:'127.0.0.1',port:4452,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});const records=[],failures=[];const axeScript=fs.readFileSync(require.resolve('axe-core/axe.min.js'),'utf8');
try{for(const [width,height] of sizes)for(const theme of ['light','dark']){
 const context=await browser.newContext({viewport:{width,height},colorScheme:theme,hasTouch:width<=1024,reducedMotion:'reduce'});await context.route('https://fonts.googleapis.com/**',r=>r.abort());await context.addInitScript(t=>{if(location.protocol==='http:')localStorage.setItem('hisabiq-theme',t);},theme);const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 async function snapshot(route,tab){const data=await page.locator('main').evaluate(main=>({documentWidth:document.documentElement.scrollWidth,controls:[...main.querySelectorAll('button,a[href],input,textarea,[role="tab"],[role="combobox"]')].filter(e=>e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden').map(e=>({role:e.getAttribute('role')||e.tagName.toLowerCase(),name:(e.getAttribute('aria-label')||e.getAttribute('placeholder')||e.textContent||'').replace(/\s+/g,' ').trim().slice(0,150),disabled:e.hasAttribute('disabled')}))}));const row={route,tab,width,height,theme,status:'enumerated',...data,errors:[...errors]};records.push(row);if(data.documentWidth>width+2||errors.length){failures.push(row);await page.screenshot({path:path.join(output,[route.replace(/\W/g,'-'),width,theme,records.length].join('-')+'.png'),fullPage:true});}}
 for(const route of routes){errors.length=0;try{
  await page.goto('http://127.0.0.1:4452/#/app/'+route,{waitUntil:'domcontentloaded'});await page.locator('main#erp-main').waitFor();await page.locator('[role="status"]').filter({hasText:/Loading/}).waitFor({state:'hidden'}).catch(()=>{});
  await snapshot(route,'default');
  // Enumerate nested tabs on representative phone/desktop views. Other sizes check default geometry.
  if(width===390||width===1440){const names=await page.locator('main').getByRole('tab').allTextContents();for(const name of names){const tab=page.locator('main').getByRole('tab',{name:name.trim(),exact:true});if(await tab.count()!==1||await tab.isDisabled())continue;await tab.click();await snapshot(route,name.trim());const subnames=await page.locator('main').getByRole('tab').allTextContents();for(const sub of subnames.filter(n=>!names.includes(n))){const child=page.locator('main').getByRole('tab',{name:sub.trim(),exact:true});if(await child.count()!==1||await child.isDisabled())continue;await child.click();await snapshot(route,name.trim()+' > '+sub.trim());}}}
  if([390,1440].includes(width)&&['dashboard','pos','parties?id=c1&role=Customer','finance','products','purchases/new','reconciliation','daybook','audit-ledger','counter'].includes(route)){
   await page.addScriptTag({content:axeScript});const violations=await page.evaluate(async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))}));});records.push({route,width,height,theme,status:'axe-measured',violations});
  }
 }catch(e){failures.push({route,width,height,theme,error:e.message});}}
 await context.close();fs.writeFileSync(path.join(output,'inventory.json'),JSON.stringify({records,failures},null,2));console.log(width,theme,records.length,'records;',failures.length,'findings');
}}finally{fs.writeFileSync(path.join(output,'inventory.json'),JSON.stringify({records,failures},null,2));await browser.close();await server.close();}}
main().catch(e=>{console.error(e);process.exitCode=1;});
